CREATE OR ALTER PROCEDURE [dbo].[uspShiftAssignment_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @EmployeeId UNIQUEIDENTIFIER = NULL
	, @ShiftId UNIQUEIDENTIFIER = NULL
	, @AssignmentStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[EmployeeId]
			, j1.[FullName] AS [EmployeeName]
			, t.[ShiftId]
			, j2.[Name] AS [ShiftName]
			, t.[WorkDate]
			, t.[PlannedStart]
			, t.[PlannedEnd]
			, t.[AssignmentStatus]
			, t.[AssignedBy]
			, t.[Note]
			, t.[CreatedDate]
		FROM [dbo].[ShiftAssignment] AS t
		LEFT JOIN [dbo].[Employee] AS j1 ON j1.[Id] = t.[EmployeeId]
		LEFT JOIN [dbo].[Shift] AS j2 ON j2.[Id] = t.[ShiftId]
		WHERE 1 = 1
			AND (@EmployeeId IS NULL OR t.[EmployeeId] = @EmployeeId)
			AND (@ShiftId IS NULL OR t.[ShiftId] = @ShiftId)
			AND (ISNULL(@AssignmentStatus, '') = '' OR t.[AssignmentStatus] = @AssignmentStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'employeeId' THEN r.[EmployeeId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'employeeId' THEN r.[EmployeeId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'employeeName' THEN r.[EmployeeName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'employeeName' THEN r.[EmployeeName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftId' THEN r.[ShiftId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftId' THEN r.[ShiftId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftName' THEN r.[ShiftName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftName' THEN r.[ShiftName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'workDate' THEN r.[WorkDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'workDate' THEN r.[WorkDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedStart' THEN r.[PlannedStart] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedStart' THEN r.[PlannedStart] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'plannedEnd' THEN r.[PlannedEnd] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'plannedEnd' THEN r.[PlannedEnd] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'assignmentStatus' THEN r.[AssignmentStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'assignmentStatus' THEN r.[AssignmentStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'assignedBy' THEN r.[AssignedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'assignedBy' THEN r.[AssignedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
